"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  DEMAND_PATH,
  DUAL_LEDGER_PATH,
  GROWTH_CONCENTRATION_CURVE,
  GROWTH_SLICES,
  HEADLINE,
  LENS_COMPARE,
  LOCAL_INTENSITY,
  PACE_CLOCKS,
  PRICE_SHOCK,
  QUEUE_METERS,
  REGION_SHARES,
  SCOREBOARD,
  SOURCE_NOTE,
  SOURCES,
  STOCK_CONCENTRATION_CURVE,
  TOP_CLUSTERS,
  US_H1_SECTORS,
  US_QUEUE_TECH,
  US_SHARE_COMPARE,
  VINTAGE_DELTAS,
  fmtGw,
  fmtPct,
  fmtPp,
  fmtTwh,
  fmtYr,
} from "@/data/ai-power-grid-concentration-202608-data";

// viz-types: vintage delta bars, Lorenz area+line, US-share bars, growth donut, queue-tech pie, demand path line, H1 sector bars, price shock bars, dual-ledger line, cluster scatter, intensity bars, queue meters, pace clocks, lens scatter | layout: default

type ViewId = "scoreboard" | "perimeters" | "queues" | "pace";
type CurveLens = "stock" | "growth";
type ClusterMetric = "load" | "pipeline";
type QueueMetric = "gw" | "yoy";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

