            subtitle={`Median IR???COD now ${fmtYr(HEADLINE.usMedianIrToCodYears)} (LBNL 2026)`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={PACE_CLOCKS}
                  layout="vertical"
                  margin={{ left: 8, right: 16 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}y`}
                    domain={[0, 8]}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={96}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="years" name="Years" radius={4}>
                    {PACE_CLOCKS.map((p) => (
                      <Cell
                        key={p.id}
                        fill={p.kind === "demand" ? "#0ea5e9" : "#f43f5e"}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Local intensity"
            subtitle="Global ~1.5% coexists with Virginia 25% / Ireland 20%"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={intensityBars}
                  layout="vertical"
                  margin={{ left: 8, right: 16 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    domain={[0, 30]}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar
                    dataKey="dcShareOfElectricityPct"
                    name="DC share %"
                    radius={4}
                  >
                    {intensityBars.map((r) => (
                      <Cell key={r.short} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top clusters"
            subtitle="Toggle IT load share vs pipeline intensity"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Y-axis"
                value={clusterMetric}
                onChange={setClusterMetric}
                options={[
                  { id: "load", label: "Global load %" },
                  { id: "pipeline", label: "Pipeline %" },
                ]}
              />
            </div>
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 8, top: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="IT load GW"
                    tick={{ fontSize: 11 }}
                    unit=" GW"
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name={
                      clusterMetric === "pipeline"
                        ? "Pipeline %"
                        : "Global share %"
                    }
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 360]} />
                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <Scatter data={clusterScatter} name="Clusters">
                    {clusterScatter.map((c) => (
                      <Cell key={c.short} fill={c.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Sources & confidence"
            subtitle="Disclosed Aug meters vs carried share ladders"
          >
            <p className="text-sm leading-relaxed text-slate-600">
              {SOURCE_NOTE}
            </p>
            <ul className="mt-4 space-y-1.5 text-sm">
              {SOURCES.map((s) => (
                <li key={s.url}>
                  <a
                    href={s.url}
                    className="text-violet-700 underline-offset-2 hover:underline"
                    target={s.url.startsWith("http") ? "_blank" : undefined}
                    rel={
                      s.url.startsWith("http")
                        ? "noopener noreferrer"
                        : undefined
                    }
                  >
                    {s.label}
                  </a>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}
    </div>
  );
}

